});
clear.addEventListener('click',()=>{
  input.value='';
  document.body.classList.remove('coffee-mode');
  input.focus();
});
input.addEventListener('input',()=>{
  clear.style.display=input.value?'block':'none';
});
document.querySelectorAll('.btn').forEach(el=>{
